<script lang="ts">
import {auth} from '#lib/auth.svelte.ts';import {anyApi} from 'convex/server';
let inviteEnabled=$state(true);
async function toggleInvite(){if(!auth.client)return;try{await auth.client.mutation(anyApi.testers.setInvitation,{enabled:!inviteEnabled});inviteEnabled=!inviteEnabled;}catch(e){error=(e as Error).message;}}
let rows=$state<any[]>([]),cursor=$state<string|null>(null),done=$state(false),busy=$state(false),error=$state('');let status=$state('active'),period=$state('week');
async function load(reset=false){if(!auth.client)return;busy=true;error='';try{if(reset)inviteEnabled=(await auth.client.query(anyApi.testers.invitation,{})).enabled;const r=await auth.client.query(anyApi.testers.members,{paginationOpts:{numItems:25,cursor:reset?null:cursor}});rows=reset?r.page:[...rows,...r.page];cursor=r.continueCursor;done=r.isDone;}catch(e){error=(e as Error).message;}finally{busy=false;}}
$effect(()=>{if(auth.client)void load(true);});
async function update(id:string){if(!auth.client)return;busy=true;try{await auth.client.mutation(anyApi.testers.setAccess,{userId:id,status,period});await load(true);}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<svelte:head><title>Member access — PuntersEdge</title></svelte:head>
<button class="btn-ghost mb-4" onclick={toggleInvite}>{inviteEnabled?'Pause new tester invitations':'Enable tester invitations'}</button><h1 class="text-3xl font-bold">Members & tester access</h1><p class="mt-3 text-haze">Individual profiles, server-enforced access periods and account status. Recent activity is approximate and sampled every five minutes.</p><div class="surface mt-5 flex flex-wrap items-end gap-3 p-4"><label class="text-sm">Apply status<select bind:value={status} class="mt-1 block min-h-11 rounded-xl bg-ink p-3"><option value="active">Active</option><option value="suspended">Suspended</option><option value="deactivated">Deactivated</option></select></label><label class="text-sm">Access from now<select bind:value={period} class="mt-1 block min-h-11 rounded-xl bg-ink p-3">{#each [['week','1 week'],['fortnight','2 weeks'],['month','1 month'],['quarter','3 months'],['halfyear','6 months'],['free','Permanent free'],['none','No complimentary grant']] as [key,label]}<option value={key}>{label}</option>{/each}</select></label><button class="btn-ghost" onclick={()=>load(true)} disabled={busy}>Refresh members</button></div>
{#if error}<p role="alert" class="mt-4 text-loss">{error}</p>{/if}<div class="mt-5 grid min-w-0 gap-3 lg:grid-cols-2">{#each rows as user(user.id)}<article class="surface min-w-0 break-words p-5"><h2 class="font-bold">{user.profile?.fullName??user.name??'Member'}</h2><p class="mt-1 text-sm text-haze">{user.email}</p><p class="mt-1 text-xs text-haze">User ID {user.id}</p>{#if user.profile}<p class="mt-3 text-sm">{user.profile.whatsapp} · {user.profile.sex}<br/>{user.profile.state} / {user.profile.lga}<br/>Date of birth: {user.profile.dob}</p>{/if}<p class="mt-3 text-sm">{user.access?.status??'active'} · {user.access?.grant??'Subscription access'}{user.access?.expiresAt?' · Until '+new Date(user.access.expiresAt).toLocaleString('en-NG'):''}</p><p class="mt-2 text-xs text-haze">{user.presence?((Date.now()-user.presence.lastSeen<360000?'🟢 Recently active':'⚪ Last seen')+' · '+new Date(user.presence.lastSeen).toLocaleString('en-NG')+' · '+user.presence.route):'No activity recorded'}</p><details class="mt-3 text-xs"><summary class="min-h-9 cursor-pointer text-pop">Recent client-reported activity</summary><ul class="mt-2 space-y-2">{#each user.presence?.events??[] as event}<li>{new Date(event.at).toLocaleString('en-NG')} · {event.event.replaceAll('_',' ')} · {event.route}</li>{:else}<li>No action history reported yet.</li>{/each}</ul></details><button class="btn-primary mt-4" disabled={busy} onclick={()=>update(user.id)}>Apply selected status & access</button></article>{:else}<p class="text-haze">{busy?'Loading members…':'No members loaded.'}</p>{/each}</div>{#if !done}<button class="btn-ghost mt-4" disabled={busy} onclick={()=>load()}>Load more members</button>{/if}
